# Contar cuántas veces sale cada palabra: el truco base de los tokenizadores.
cuenta = {}
for p in "el maestro forja la katana y el maestro la templa".split():
    cuenta[p] = cuenta.get(p, 0) + 1
print(cuenta)
print("Más frecuente:", max(cuenta, key=lambda p: cuenta[p]))

def normalizar(valor, minimo, maximo):
    return (valor - minimo) / (maximo - minimo)

print(normalizar(60, 50, 70))   # 0.5

# Una función puede devolver varias cosas a la vez (una tupla).
def rango(valores):
    return min(valores), max(valores)

bajo, alto = rango([3, 9, 1, 7])
print(bajo, alto)

import math

def distancia(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def coseno(a, b):
    punto = sum(x * y for x, y in zip(a, b))
    return punto / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))

