class Katana:
    def __init__(self, nombre, dureza):
        self.nombre = nombre
        self.dureza = dureza

    def apta(self):
        return 58 <= self.dureza <= 64

    def __str__(self):
        estado = "apta" if self.apta() else "defectuosa"
        return f"{self.nombre}: {self.dureza} HRC, {estado}"

